(5462003, 786776, 23484, '<td valign="top">Great abstract.</td>', 'Great abstract.', '2009-05-01 18:34:53.000000', NULL, 1),
(5462005, 784850, 101256, '<td valign="top">A good solid image that is crisp, sharp and properly framed and composed - a technical success in every way. From an artistic standpoint, it has significant impact being richly colored with excellant detail in the foreground. This image would have worked as a black and white as well. A perfect demonstration of the power of properly controlled light and focus. A top ten image and a very strong contender for a ribbon. Well done.</td>', 'A good solid image that is crisp, sharp and properly framed and composed - a technical success in every way. From an artistic standpoint, it has significant impact being richly colored with excellant detail in the foreground. This image would have worked as a black and white as well. A perfect demonstration of the power of properly controlled light and focus. A top ten image and a very strong contender for a ribbon. Well done.', '2009-05-01 18:35:19.000000', NULL, 1),
(5462006, 785966, 23484, '<td valign="top">Outstanding.</td>', 'Outstanding.', '2009-05-01 18:36:22.000000', NULL, 1),
