(5465364, 785047, 106109, '<td valign="top">Great macro.</td>', 'Great macro.', '2009-05-03 12:33:02.000000', NULL, 1),
(5465365, 786554, 102811, '<td valign="top">What a wonderfully unique image that works amazingingly well with all the disperate components working together to create a stunning pictoral story. Only negative is the tulips look a bit over processed (topaz?) giving an otherwise brilliant image a slightly unatural apperance in the foreground. Top marks from me and good luck for the remainder of the challenge.</td>', 'What a wonderfully unique image that works amazingingly well with all the disperate components working together to create a stunning pictoral story. Only negative is the tulips look a bit over processed (topaz?) giving an otherwise brilliant image a slightly unatural apperance in the foreground. Top marks from me and good luck for the remainder of the challenge.', '2009-05-03 12:33:34.000000', NULL, 1),
(5465369, 785821, 106109, '<td valign="top">Nice capture. Could have more DOF and sharpness.</td>', 'Nice capture. Could have more DOF and sharpness.', '2009-05-03 12:34:34.000000', NULL, 1),
(5465370, 785890, 102581, '<td valign="top">Great shot!</td>', 'Great shot!', '2009-05-03 12:35:07.000000', NULL, 1),
(5465371, 783602, 106109, '<td valign="top">Excellent POV.</td>', 'Excellent POV.', '2009-05-03 12:35:49.000000', NULL, 1),
(5465374, 786870, 106109, '<td valign="top">Funny title.</td>', 'Funny title.', '2009-05-03 12:37:31.000000', NULL, 1),
