INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5470456, 786913, 83313, '<td valign="top">Not sure this will be exceptionally high scoring, but I think it''s a good use of blur to make me focus on the little girl. Has a melethish look to it.</td>', 'Not sure this will be exceptionally high scoring, but I think it''s a good use of blur to make me focus on the little girl. Has a melethish look to it.', '2009-05-05 15:23:56.000000', NULL, 1),
(5470459, 781299, 83313, '<td valign="top">Is this a miniature? It''s an odd shot but engaging. Gets a higher voter for forcing me to pause to examine it.</td>', 'Is this a miniature? It''s an odd shot but engaging. Gets a higher voter for forcing me to pause to examine it.', '2009-05-05 15:25:44.000000', NULL, 1),
(5470463, 786993, 83313, '<td valign="top">This is just not grabbing my attention, I''m afraid. I think that is just a personal opinion however, and others will likely appreciate this shot much more.</td>', 'This is just not grabbing my attention, I''m afraid. I think that is just a personal opinion however, and others will likely appreciate this shot much more.', '2009-05-05 15:27:56.000000', NULL, 1),
(5470465, 784781, 83313, '<td valign="top">Too much JPEG compression is robbing some clarity from this photo. At 94k in size, you had a lot more file size overhead to use. Otherwise, a great image.</td>', 'Too much JPEG compression is robbing some clarity from this photo. At 94k in size, you had a lot more file size overhead to use. Otherwise, a great image.', '2009-05-05 15:29:27.000000', NULL, 1),
