INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(5473400, 786402, 29011, '<td valign="top">Really like this shot. The sky looks awesome, and I like the sliver of ocean below. Only nitpick, the hint of the elements along the shoreline in the bottom right corner deduct from the mood of the shot for me. Crop that part off perhaps? Still, an easy 7 from me.</td>', 'Really like this shot. The sky looks awesome, and I like the sliver of ocean below. Only nitpick, the hint of the elements along the shoreline in the bottom right corner deduct from the mood of the shot for me. Crop that part off perhaps? Still, an easy 7 from me.', '2009-05-06 19:18:16.000000', NULL, 1),
(5473404, 786233, 102776, '<td valign="top">Nice. Imposed human emotion because we recognise the stance in us.</td>', 'Nice. Imposed human emotion because we recognise the stance in us.', '2009-05-06 19:18:44.000000', NULL, 1),
(5473405, 784185, 102776, '<td valign="top">I can feel the motion in this image and want to follow.</td>', 'I can feel the motion in this image and want to follow.', '2009-05-06 19:19:33.000000', NULL, 1),
(5473408, 783601, 102776, '<td valign="top">I like the framing and DOF. I think that the light is a bit stark and washes away the richness of the purple in the petals. I feel that the centre of the flower is lovely and rich.</td>', 'I like the framing and DOF. I think that the light is a bit stark and washes away the richness of the purple in the petals. I feel that the centre of the flower is lovely and rich.', '2009-05-06 19:21:53.000000', NULL, 1),
(5473410, 786951, 29011, '<td valign="top">One of my top5 picks from the challenge. Wonderful catch of the moment. I like the choice of title, it''s simple and connects extremely well. Toning looks great, if anything(doesn''t detract from the though) the vignette doesn''t look as even coming in, in the top left section of the shot. Hope this shot does well. Good luck! :)</td>', 'One of my top5 picks from the challenge. Wonderful catch of the moment. I like the choice of title, it''s simple and connects extremely well. Toning looks great, if anything(doesn''t detract from the though) the vignette doesn''t look as even coming in, in the top left section of the shot. Hope this shot does well. Good luck! :)', '2009-05-06 19:22:19.000000', NULL, 1),
(5473413, 783137, 102776, '<td valign="top">Love the flowers but feel the impact is lost from those trees encroaching from the background.</td>', 'Love the flowers but feel the impact is lost from those trees encroaching from the background.', '2009-05-06 19:22:46.000000', NULL, 1),
(5473414, 779269, 102776, '<td valign="top">Interesting study. Like the overall thoughtful feel. I am sure that this would score higher if the persons behind the soldier were not there so that he had a harder edge to emerge from the background.</td>', 'Interesting study. Like the overall thoughtful feel. I am sure that this would score higher if the persons behind the soldier were not there so that he had a harder edge to emerge from the background.', '2009-05-06 19:22:51.000000', NULL, 1),
(5473415, 784919, 102776, '<td valign="top">Love the tones and the inviting leading feel.</td>', 'Love the tones and the inviting leading feel.', '2009-05-06 19:22:58.000000', NULL, 1),
(5473417, 784759, 102776, '<td valign="top">I like the framing and "pose".  I think that the light let you down as I feel that his eyes don''t quite punch out at you.</td>', 'I like the framing and "pose".  I think that the light let you down as I feel that his eyes don''t quite punch out at you.', '2009-05-06 19:23:02.000000', NULL, 1),
