(5476343, 784998, 102776, '<td valign="top">Congratulations! I so like this image. Thank you.</td>', 'Congratulations! I so like this image. Thank you.', '2009-05-08 07:38:18.000000', NULL, 0),
(5476344, 784765, 67152, '<td valign="top">Fantastic image Marac and congrats on a great finish.  I love the personality and ''humanity'' of the shot.  Just look at those comment scores!</td>', 'Fantastic image Marac and congrats on a great finish.  I love the personality and ''humanity'' of the shot.  Just look at those comment scores!', '2009-05-08 07:39:40.000000', NULL, 0),
